function validSubstringCount(word1, word2) {
  const need = new Array(26).fill(0);
  for (let i = 0; i < word2.length; i++) {
    need[word2.charCodeAt(i) - 97]++;
  }
  let missing = word2.length;
  let right = 0;
  let count = 0;
  for (let left = 0; left < word1.length; left++) {
    while (right < word1.length && missing > 0) {
      const added = word1.charCodeAt(right) - 97;
      if (need[added] > 0) {
        missing--;
      }
      need[added]--;
      right++;
    }
    if (missing > 0) {
      break;
    }
    count += word1.length - right + 1;
    const removed = word1.charCodeAt(left) - 97;
    need[removed]++;
    if (need[removed] > 0) {
      missing++;
    }
  }
  return count;
}

