function validSubstringCount(word1, word2) {
  // For every substring, try to take word2's letters out of a copy of its letter counts one by one.
  let total = 0;
  for (let i = 0; i < word1.length; i++) {
    const have = new Map();
    for (let j = i; j < word1.length; j++) {
      have.set(word1[j], (have.get(word1[j]) || 0) + 1);
      const rest = new Map(have);
      let fits = true;
      for (const ch of word2) {
        if (!rest.get(ch)) { fits = false; break; }
        rest.set(ch, rest.get(ch) - 1);
      }
      if (fits) total++;
    }
  }
  return total;
}

