function generate(rand, size) {
  const large = size === 'large';
  // A small alphabet makes letters repeat, so many windows become valid; 26 letters make them rare.
  const k = large ? [2, 4, 26][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 3);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, k);
  const letter = () => alphabet[Math.floor(rand() * k)];
  const n = large ? 10000 : 1 + Math.floor(rand() * 12);
  // Large cases pick a short, medium or long word2, so the shortest valid windows are tiny, mid-sized or huge.
  const m = large ? [1 + Math.floor(rand() * 10), 50 + Math.floor(rand() * 500), 3000 + Math.floor(rand() * 5000)][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 4);
  let word1 = '';
  for (let i = 0; i < n; i++) word1 += letter();
  let word2 = '';
  for (let i = 0; i < m; i++) word2 += letter();
  return [word1, word2];
}
